// Porte l'expérience des personnages ciblés au maximum de leur niveau courant
// (300/300 au niveau 1, 900/900 au niveau 2…), ce qui débloque la macro de
// montée de niveau côté joueur. C'est le seul geste du MJ dans la progression :
// le choix de la classe reste au joueur.
(async () => {
    const t = (key, data) => data
        ? game.i18n.format("FQCARDENGINE." + key, data)
        : game.i18n.localize("FQCARDENGINE." + key);

    if (!game.user.isGM) return ui.notifications.warn(t("LevelUpGMOnly"));

    // Les cibles d'abord (le geste habituel du moteur), les tokens sélectionnés
    // à défaut : le MJ n'a pas toujours de cible posée sur sa propre scène.
    const tokens = game.user.targets.size ? [...game.user.targets] : (canvas.tokens?.controlled ?? []);
    const actors = [...new Set(tokens.map(token => token.actor).filter(actor => actor?.type === "character"))];
    if (!actors.length) return ui.notifications.warn(t("LevelUpNoTarget"));

    const filled = [];
    for (const actor of actors) {
        // Au niveau maximal, dnd5e ne définit plus de palier : `xp.max` vaut
        // l'infini, il n'y a plus rien à remplir.
        if (actor.system.details.level >= CONFIG.DND5E.maxLevel) {
            ui.notifications.warn(t("LevelUpMaxCharacterLevel", {actor: actor.name, max: CONFIG.DND5E.maxLevel}));
            continue;
        }

        const xp = actor.system.details.xp;
        if (xp.value >= xp.max) {
            ui.notifications.info(t("LevelUpXpAlreadyFull", {actor: actor.name, value: xp.value, max: xp.max}));
            continue;
        }

        await actor.update({"system.details.xp.value": xp.max});
        filled.push(t("LevelUpXpEntry", {actor: actor.name, value: xp.max, max: xp.max}));
    }

    if (filled.length) ui.notifications.info(t("LevelUpXpFilled", {entries: filled.join(", ")}));
})();
